/* ===================== BÀI 1 · 8086 và bức tranh hệ thống ===================== */
/* Bài 1 · 8086 và bức tranh hệ thống (AMTS-EMB-002-M01-L01, X86-001) — sinh bởi tools/author/mpu8086/l01.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P1=[{"label": "Ví dụ: CPU nạp và chạy từng lệnh", "code": "; Ví dụ 1: CPU nạp từng lệnh từ bộ nhớ rồi thực thi\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AH, 02H                 ; hàm 02h của DOS: in ký tự trong DL\n        MOV     DL, 'A'                 ; DL = 41h, mã ASCII của chữ A\n        INT     21H                     ; gọi dịch vụ DOS, chữ A hiện ra\n        MOV     AX, 4C00H               ; hàm 4Ch: trả quyền cho DOS, mã thoát 0\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bấm Từng bước. Ở phần Mã máy và chu kỳ, mỗi lệnh có địa chỉ, các byte mã máy và số chu kỳ; IP tăng đúng bằng độ dài lệnh (2, 2, 2, 3, 2 byte). Hình địa chỉ vật lý cho CS × 16 + IP. Lệnh INT 21h (51 chu kỳ) gọi DOS in chữ A. Đoán trước: tới MOV AX, 4C00h, IP trước lệnh bằng bao nhiêu? Đáp án 0006h."}, {"label": "Ví dụ: đọc và ghi ô nhớ dữ liệu", "code": "; Ví dụ 2: dữ liệu nằm trong bộ nhớ, CPU đọc vào thanh ghi\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nsoA     DB      25                      ; ô nhớ chứa 25 = 19h\nsoB     DB      17                      ; 17 = 11h\ntong    DB      ?                       ; ô nhớ nhận kết quả\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA               ; số hiệu đoạn dữ liệu\n        MOV     DS, AX                  ; DS trỏ vào đoạn dữ liệu\n        MOV     AL, soA                 ; đọc 1 byte từ bộ nhớ vào AL\n        ADD     AL, soB                 ; đọc thêm 1 byte rồi cộng trong CPU\n        MOV     tong, AL                ; ghi kết quả ngược ra bộ nhớ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Xem phần Bộ nhớ ở đoạn dữ liệu: soA = 19h, soB = 11h. MOV AL, soA và ADD AL, soB đọc bộ nhớ qua bus; MOV tong, AL ghi 2Ah ra ô tong. Đoán trước: sau ADD, AL bằng bao nhiêu (hệ 16)? Đáp án 2Ah."}, {"label": "Ví dụ: màn hình văn bản là vùng nhớ B800h", "code": "; Ví dụ 3: màn hình văn bản là một vùng bộ nhớ (B800:0000)\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 0B800H              ; đoạn của bộ nhớ màn hình văn bản\n        MOV     ES, AX                  ; ES trỏ vào bộ nhớ màn hình\n        MOV     BYTE PTR ES:[0], 'O'    ; ô hàng 0, cột 0: mã ký tự\n        MOV     BYTE PTR ES:[1], 07H    ; thuộc tính: chữ xám, nền đen\n        MOV     BYTE PTR ES:[2], 'K'    ; ô hàng 0, cột 1\n        MOV     BYTE PTR ES:[3], 07H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "ES = B800h là đoạn của bộ nhớ màn hình. Bốn lệnh MOV ghi 4 byte (ký tự, thuộc tính, ký tự, thuộc tính) và chữ OK hiện ở dòng đầu Màn hình DOS mà không cần INT 21h. Mỗi lệnh 18 chu kỳ: 10 + EA 6 + tiền tố đoạn ES 2. Đoán trước: lệnh ghi chữ K ghi vào địa chỉ vật lý nào? Đáp án B8002h."}, {"label": "Lỗi: quên nạp ES, chữ không lên màn hình", "code": "; Lỗi: quên nạp ES nên chữ không lên màn hình\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n; thiếu MOV AX, 0B800h / MOV ES, AX\n        MOV     BYTE PTR ES:[0], 'O'    ; ES vẫn là đoạn PSP do DOS đặt\n        MOV     BYTE PTR ES:[1], 07H\n        MOV     BYTE PTR ES:[2], 'K'\n        MOV     BYTE PTR ES:[3], 07H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: thiếu MOV AX, 0B800h / MOV ES, AX. Lúc bắt đầu ES = đoạn PSP (0700h) nên 4 byte bị ghi vào 0700:0000, đè lên lệnh INT 20h đầu PSP. Màn hình vẫn trống. Sửa: thêm hai lệnh nạp ES như Ví dụ 3. Đoán trước: tới lệnh ghi đầu tiên, ES bằng bao nhiêu? Đáp án 0700h (đoạn PSP, giả định của trình mô phỏng)."}, {"label": "Bẫy: cổng 60h không phải ô nhớ 60h", "code": "; Bẫy: cổng 60h không phải ô nhớ 60h\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkhoang  DB      60H DUP(0)              ; 96 byte: độ lệch 0000h…005Fh\no60     DB      5AH                     ; ô nhớ ở độ lệch 0060h\ntuNho   DB      ?                       ; byte đọc từ bộ nhớ\ntuCong  DB      ?                       ; byte đọc từ cổng\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     BX, 60H                 ; BX = độ lệch 0060h\n        MOV     AL, [BX]                ; đọc BỘ NHỚ tại DS:0060h\n        MOV     tuNho, AL\n        IN      AL, 60H                 ; đọc CỔNG 60h: không gian khác\n        MOV     tuCong, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Cùng số 60h: MOV AL, [BX] đọc ô nhớ DS:0060h (5Ah), IN AL, 60h đọc cổng 60h (FFh vì cổng chưa gắn thiết bị trên trình mô phỏng). Xem biến tuNho, tuCong ở phần Bộ nhớ. Hai lệnh đi qua hai không gian địa chỉ khác nhau. Đoán trước: sau IN AL, 60h, AL còn là 5Ah không? Đáp án không (FFh)."}, {"label": "Lỗi: quên trả quyền cho DOS", "code": "; Lỗi: quên trả quyền cho DOS\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AH, 02H\n        MOV     DL, 'A'\n        INT     21H                     ; in A\n; thiếu MOV AX, 4C00h / INT 21h\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: không có lệnh trả quyền cho DOS. Sau INT 21h, CPU nạp tiếp các byte 00 00 (lệnh ADD [BX+SI], AL) và chạy mãi; IP quay vòng về 0000h nên chữ A được in lại nhiều lần. Trình mô phỏng dừng ở 2 000 000 lệnh. Trên máy thật vùng nhớ phía sau là giá trị bất kỳ: kết quả không xác định. Sửa: thêm MOV AX, 4C00h / INT 21h như Ví dụ 1. Đoán trước: tới byte đầu sau INT 21h, CPU có dừng không? Đáp án không."}, {"label": "Ví dụ: thanh ghi nhanh hơn ô nhớ", "code": "; Ví dụ 7: thanh ghi trong CPU so với ô nhớ ngoài CPU\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nx       DW      1000                    ; cộng thẳng trên ô nhớ\ny       DW      1000                    ; chép vào thanh ghi rồi mới cộng\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n; Cách 1: mỗi lệnh đọc và ghi bộ nhớ\n        ADD     x, 5                    ; 17 + 6 = 23 chu kỳ\n        ADD     x, 5\n        ADD     x, 5\n; Cách 2: một lần đọc, một lần ghi\n        MOV     BX, y                   ; 8 + 6 = 14 chu kỳ\n        ADD     BX, 5                   ; 4 chu kỳ\n        ADD     BX, 5\n        ADD     BX, 5\n        MOV     y, BX                   ; 9 + 6 = 15 chu kỳ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Cùng kết quả 1015 (03F7h) nhưng cách 1 tốn 3 × 23 = 69 chu kỳ, cách 2 tốn 14 + 3 × 4 + 15 = 41 chu kỳ. Đổi lại cách 2 dài hơn: 17 byte so với 15 byte. Xem cột chu kỳ ở phần Mã máy và chu kỳ. Đoán trước: tới MOV y, BX, BX bằng bao nhiêu (hệ 16)? Đáp án 03F7h."}];
const sim1=makeX86Sim(document.getElementById("x86-l1"),{id:"s1",presets:P1,file:"BAI1.ASM"});
makeX86Ex(document.getElementById("ex-l1"),sim1,[{"t": "Phím trong ngoặc vuông", "d": "Đọc một phím bằng INT 21h hàm 08h (không hiện). Ghi mã ASCII của phím vào biến phim, rồi in ba ký tự: dấu [, chính phím đó, dấu ]. Kết thúc bằng INT 21h hàm 4Ch. Phím là một ký tự ASCII in được (20h–7Eh).", "start": "; Bài tập 1: đọc phím, cất vào bộ nhớ, in trong ngoặc vuông\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nphim    DB      ?                       ; giữ nguyên tên biến\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc một phím, không hiện\n        INT     21H                     ; AL = mã ASCII của phím\n; Viết code ở đây: cất AL vào phim,\n; rồi in [ , phím, ] bằng INT 21h hàm 02h\n\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "A", "out": "[A]", "mem": [{"at": "phim", "bytes": [65]}]}, {"in": "z", "out": "[z]", "mem": [{"at": "phim", "bytes": [122]}]}, {"in": "7", "out": "[7]", "mem": [{"at": "phim", "bytes": [55]}]}, {"in": "$", "out": "[$]", "mem": [{"at": "phim", "bytes": [36]}]}, {"in": " ", "out": "[ ]", "mem": [{"at": "phim", "bytes": [32]}]}, {"in": "~", "out": "[~]", "mem": [{"at": "phim", "bytes": [126]}]}]}, {"t": "Chữ thường thành chữ hoa", "d": "Đọc một phím chữ thường a–z bằng INT 21h hàm 08h. Ghi phím gốc vào biến goc, chữ hoa tương ứng vào biến hoa, rồi in chữ hoa bằng INT 21h hàm 02h. Kết thúc bằng INT 21h hàm 4Ch. Dữ liệu chấm luôn là chữ thường a–z.", "start": "; Bài tập 2: chữ thường thành chữ hoa\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ngoc     DB      ?                       ; phím gốc (chữ thường)\nhoa     DB      ?                       ; chữ hoa tương ứng\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc một phím, không hiện\n        INT     21H\n; Viết code ở đây: cất goc, tính hoa,\n; in chữ hoa bằng INT 21h hàm 02h\n\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "a", "out": "A", "mem": [{"at": "goc", "bytes": [97]}, {"at": "hoa", "bytes": [65]}]}, {"in": "z", "out": "Z", "mem": [{"at": "goc", "bytes": [122]}, {"at": "hoa", "bytes": [90]}]}, {"in": "m", "out": "M", "mem": [{"at": "goc", "bytes": [109]}, {"at": "hoa", "bytes": [77]}]}, {"in": "q", "out": "Q", "mem": [{"at": "goc", "bytes": [113]}, {"at": "hoa", "bytes": [81]}]}, {"in": "b", "out": "B", "mem": [{"at": "goc", "bytes": [98]}, {"at": "hoa", "bytes": [66]}]}]}, {"t": "Cộng 4 chữ số nhanh hơn", "d": "Đọc lần lượt 4 phím chữ số 0–9 bằng INT 21h hàm 08h và ghi tổng giá trị của chúng (0–36) vào biến tong (1 byte). Code mẫu đã cho kết quả đúng nhưng cộng và đếm thẳng trên ô nhớ nên chậm. Viết lại để chương trình đạt cả giới hạn chu kỳ và giới hạn số byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: cộng 4 chữ số, giữ dữ liệu trong thanh ghi\n; Bản này cho kết quả đúng nhưng chậm: mỗi vòng\n; đọc và ghi bộ nhớ nhiều lần. Hãy viết lại.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntong    DB      ?                       ; tổng giá trị 4 chữ số\ndem     DB      ?                       ; số phím còn phải đọc\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     tong, 0\n        MOV     dem, 4\ndoc:\n        MOV     AH, 08H                 ; đọc một phím chữ số\n        INT     21H\n        SUB     AL, '0'                 ; '7' (37h) → 7\n        ADD     tong, AL                ; cộng thẳng vào ô nhớ\n        DEC     dem                     ; đếm lùi trên ô nhớ\n        JNZ     doc\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "1234", "mem": [{"at": "tong", "bytes": [10]}]}, {"in": "0000", "mem": [{"at": "tong", "bytes": [0]}]}, {"in": "9999", "mem": [{"at": "tong", "bytes": [36]}]}, {"in": "9000", "mem": [{"at": "tong", "bytes": [9]}]}, {"in": "0009", "mem": [{"at": "tong", "bytes": [9]}]}, {"in": "5371", "mem": [{"at": "tong", "bytes": [16]}]}], "perf": {"cycles": 420, "bytes": 32}}]);

makeQuiz("quiz1","score1",[{"q": "Một bo 8086 tối thiểu có EPROM và RAM. Sau RESET, chip nào phải trả lời khi CPU đọc địa chỉ FFFF0h?", "o": ["RAM, vì chương trình luôn được nạp vào RAM trước khi chạy", "8255, vì nó cấp lệnh khởi động cho CPU qua cổng song song", "Không chip nào, vì 8086 có ROM khởi động nằm sẵn bên trong chip", "EPROM, vì CPU nạp lệnh đầu tiên ở FFFF0h và RAM chưa có chương trình"], "a": 3, "e": "Sau RESET, CS = FFFFh, IP = 0000h nên địa chỉ nạp lệnh đầu tiên là FFFF0h. Lúc đó RAM chưa có gì (nội dung không xác định), và 8086 không có ROM bên trong như vi điều khiển; vì vậy EPROM phải phủ địa chỉ này."}, {"q": "Trên trình mô phỏng của khóa, ô nhớ DS:0060h chứa 5Ah và cổng 60h chưa gắn thiết bị. Sau đoạn code sau, DL và AL bằng bao nhiêu?<pre class=\"mp-asm\">        MOV     BX, 0060H\n        MOV     DL, [BX]\n        IN      AL, 60H<\/pre>", "o": ["DL = 5Ah, AL = 5Ah, vì hai lệnh đọc cùng một byte", "DL = 5Ah (ô nhớ DS:0060h), AL = FFh (cổng 60h trống)", "DL = FFh (cổng 60h trống), AL = 5Ah (ô nhớ 00060h)", "DL = 60h, AL = 60h, vì cả hai lệnh chỉ chép số 60h"], "a": 1, "e": "MOV với toán hạng bộ nhớ đặt M/IO = 1 nên DL nhận byte ở ô nhớ DS:0060h; IN đặt M/IO = 0 nên AL nhận byte từ cổng 60h: hai không gian địa chỉ tách biệt. FFh là quy ước của trình mô phỏng cho cổng trống; trên máy thật giá trị phụ thuộc thiết bị (Ví dụ 5)."}, {"q": "Chương trình .EXE sau chạy trên DOS. Màn hình hiện gì?<pre class=\"mp-asm\">        MOV     BYTE PTR ES:[0], 'O'\n        MOV     BYTE PTR ES:[1], 07H\n        MOV     AX, 4C00H\n        INT     21H<\/pre>", "o": ["Không có chữ O nào: ES đang trỏ vào PSP nên byte được ghi vào PSP", "Chữ O ở góc trên trái màn hình, vì DOS luôn đặt sẵn ES = B800h", "Chữ O ở vị trí con trỏ hiện tại, giống INT 21h hàm 02h", "Trình dịch báo lỗi vì không được ghi bộ nhớ qua tiền tố ES"], "a": 0, "e": "Với chương trình .EXE, DOS đặt ES = DS = đoạn PSP. Muốn ghi màn hình phải tự nạp ES = B800h (Ví dụ 3, Ví dụ 4)."}, {"q": "Theo bảng thời gian lệnh 8086 (không trạng thái chờ, word ở địa chỉ chẵn), lệnh nào tốn nhiều chu kỳ nhất?", "o": ["<code>MOV BX, x<\/code>", "<code>MOV x, BX<\/code>", "<code>ADD BX, 5<\/code>", "<code>ADD x, 5<\/code> với x là biến word"], "a": 3, "e": "ADD bộ nhớ, số tức thời: 17 + EA 6 = 23 chu kỳ vì phải đọc rồi ghi lại ô nhớ. MOV BX, x là 14, MOV x, BX là 15, ADD BX, 5 chỉ 4 vì không đi qua bus."}, {"q": "Trên một bo bare-metal không có DOS, chương trình gọi <code>MOV AH, 02h<\/code>, <code>MOV DL, 'A'<\/code>, <code>INT 21h<\/code>. Phát biểu nào đúng?", "o": ["8086 có sẵn lệnh in ký tự trong chip nên chữ A vẫn hiện ra", "CPU vẫn nhảy theo vectơ 21h trong RAM; không có DOS thì không in chữ A", "Trình dịch báo lỗi vì INT 21h chỉ dịch được khi máy có DOS", "Lệnh INT 21h tự gửi chữ A ra cổng nối tiếp của chip 8251"], "a": 1, "e": "INT là lệnh của CPU, còn dịch vụ in ký tự là chương trình DOS cài trong RAM. Không có DOS, vectơ 21h trỏ tới nơi không xác định (hoặc chương trình bạn tự viết)."}]);

